-- ----------------------------
-- Table structure for payment_callbacks
-- ----------------------------
DROP TABLE IF EXISTS "public"."payment_callbacks";
CREATE TABLE "public"."payment_callbacks" (
  "id" int4 NOT NULL DEFAULT nextval('payment_callbacks_id_seq'::regclass),
  "transaction_id" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "payment_gateway" varchar(50) COLLATE "pg_catalog"."default" NOT NULL,
  "external_id" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "payment_method" varchar(100) COLLATE "pg_catalog"."default",
  "status" varchar(50) COLLATE "pg_catalog"."default" NOT NULL,
  "amount" numeric(15,2) NOT NULL,
  "currency" varchar(10) COLLATE "pg_catalog"."default" DEFAULT 'IDR'::character varying,
  "fee" numeric(15,2) DEFAULT 0,
  "net_amount" numeric(15,2),
  "reference_id" varchar(255) COLLATE "pg_catalog"."default",
  "payment_channel" varchar(100) COLLATE "pg_catalog"."default",
  "bank_code" varchar(20) COLLATE "pg_catalog"."default",
  "va_number" varchar(50) COLLATE "pg_catalog"."default",
  "qr_string" text COLLATE "pg_catalog"."default",
  "ewallet_type" varchar(50) COLLATE "pg_catalog"."default",
  "callback_data" jsonb,
  "signature" text COLLATE "pg_catalog"."default",
  "is_verified" bool DEFAULT false,
  "processed_at" timestamp(6),
  "created_at" timestamp(6) DEFAULT now(),
  "updated_at" timestamp(6) DEFAULT now()
)
;
COMMENT ON COLUMN "public"."payment_callbacks"."payment_gateway" IS 'xendit, midtrans, duitku, dll';
COMMENT ON COLUMN "public"."payment_callbacks"."status" IS 'PENDING, PAID, FAILED, EXPIRED, CANCELLED';
COMMENT ON COLUMN "public"."payment_callbacks"."callback_data" IS 'Raw callback data dari payment gateway';
COMMENT ON COLUMN "public"."payment_callbacks"."is_verified" IS 'Apakah signature callback sudah diverifikasi';

