-- ----------------------------
-- Table structure for transactions
-- ----------------------------
DROP TABLE IF EXISTS "public"."transactions";
CREATE TABLE "public"."transactions" (
  "id" int4 NOT NULL DEFAULT nextval('transactions_id_seq'::regclass),
  "kode_transaksi" varchar(50) COLLATE "pg_catalog"."default" NOT NULL,
  "title" text COLLATE "pg_catalog"."default",
  "buyer_id" int4,
  "seller_id" int4,
  "status" varchar(30) COLLATE "pg_catalog"."default",
  "total_amount" numeric(12,2) NOT NULL,
  "fee_amount" numeric(12,2) DEFAULT 0,
  "amount_paid" numeric(12,2) DEFAULT 0,
  "is_funded" bool DEFAULT false,
  "funded_at" timestamp(6),
  "notes" text COLLATE "pg_catalog"."default",
  "created_at" timestamp(6) DEFAULT now(),
  "updated_at" timestamp(6) DEFAULT now(),
  "created_by" int4,
  "roles" varchar(50) COLLATE "pg_catalog"."default",
  "fee_by" varchar(50) COLLATE "pg_catalog"."default",
  "categ_id" int4,
  "completed_at" timestamp(6),
  "release_date" timestamp(6),
  "shipping_option" bool DEFAULT false,
  "shipping_fee" int4 DEFAULT 0,
  "work_duration" int4,
  "voucher_id" int4,
  "voucher_discount" numeric(10,2) DEFAULT 0
)
;
COMMENT ON COLUMN "public"."transactions"."status" IS 'draft, waiting payment, funded, completed, cancelled, refunded, disputed, Disbursed
draft
wait_payment
pending
Transaksi dibuat, menunggu pembayaran dari pembeli.

funded
Dana sudah masuk ke rekber, menunggu konfirmasi pengiriman barang/jasa dari penjual.
 
completed
Transaksi selesai, dana sudah diteruskan ke penjual.

cancelled
Transaksi dibatalkan sebelum dana masuk atau sebelum proses pengiriman.

refunded
Dana dikembalikan ke pembeli (misal: barang tidak dikirim/diterima, atau ada dispute).';
COMMENT ON COLUMN "public"."transactions"."roles" IS 'pembeli, penjual';
COMMENT ON COLUMN "public"."transactions"."fee_by" IS 'buyer, seller';
COMMENT ON COLUMN "public"."transactions"."categ_id" IS '1=fisik, 2=digital, 3=jasa';

